-- Generated by drizzle-kit, then edited by hand: STRICT, and the triggers that keep book_setting's version and creation
-- honest. The schema tests fail if either goes missing.
CREATE TABLE `book_setting` (
	`id` integer PRIMARY KEY,
	`quiet_after_days` integer NOT NULL,
	`created_at` integer NOT NULL,
	`created_by` text NOT NULL,
	`updated_at` integer NOT NULL,
	`updated_by` text NOT NULL,
	`version` integer NOT NULL,
	CONSTRAINT `fk_book_setting_created_by_account_id_fk` FOREIGN KEY (`created_by`) REFERENCES `account`(`id`),
	CONSTRAINT `fk_book_setting_updated_by_account_id_fk` FOREIGN KEY (`updated_by`) REFERENCES `account`(`id`),
	CONSTRAINT "book_setting_single" CHECK("id" = 1),
	CONSTRAINT "book_setting_quiet_after_days_range" CHECK("quiet_after_days" between 7 and 180),
	CONSTRAINT "book_setting_version_positive" CHECK("version" >= 1),
	CONSTRAINT "book_setting_updated_after_created" CHECK("updated_at" >= "created_at")
) STRICT;
--> statement-breakpoint
CREATE TRIGGER `book_setting_version_moves_by_one` BEFORE UPDATE ON `book_setting`
WHEN NEW.`version` IS NOT OLD.`version` + 1
BEGIN
	SELECT RAISE(ABORT, 'stale_version');
END;
--> statement-breakpoint
CREATE TRIGGER `book_setting_creation_is_fixed` BEFORE UPDATE ON `book_setting`
WHEN NEW.`created_at` IS NOT OLD.`created_at` OR NEW.`created_by` IS NOT OLD.`created_by`
BEGIN
	SELECT RAISE(ABORT, 'creation_is_fixed');
END;
